import numpy as np
from scipy import sparse
from scipy.sparse import _sparsetools
class FastOp(sparse.linalg.LinearOperator):
 def __init__(self,A): self.A=A;self.shape=A.shape;self.dtype=A.dtype
 def _matvec(self,v):
  a=self.A;y=np.zeros(a.shape[0],dtype=np.result_type(a.dtype,v.dtype));_sparsetools.csr_matvec(a.shape[0],a.shape[1],a.indptr,a.indices,a.data,v,y);return y
class Solver:
 def solve(self,p,**kwargs):
  A=p['matrix'];n=A.shape[0];w,x=sparse.linalg.eigs(FastOp(A),k=p['k'],v0=np.ones(n,dtype=A.dtype),maxiter=n*200,ncv=20)
  q=list(zip(w,x.T));q.sort(key=lambda z:-abs(z[0]));return [z[1] for z in q]

