import numpy as np
from scipy import sparse
from numba import njit

@njit(cache=True)
def _mv(indptr,indices,data,v):
 n=indptr.size-1
 out=np.zeros(n,dtype=np.float64)
 for i in range(n):
  s=0.0
  for j in range(indptr[i],indptr[i+1]):
   s += data[j]*v[indices[j]]
  out[i]=s
 return out

class Solver:
 def solve(self,p,**kwargs):
  A=p['matrix'];n=A.shape[0]; ip=A.indptr; ix=A.indices; dat=A.data
  op=sparse.linalg.LinearOperator((n,n),matvec=lambda v:_mv(ip,ix,dat,v),dtype=A.dtype)
  w,x=sparse.linalg.eigs(op,k=p['k'],v0=np.ones(n,dtype=A.dtype),maxiter=n*200,ncv=20)
  q=list(zip(w,x.T));q.sort(key=lambda z:-abs(z[0]));return [z[1] for z in q]
